mkdir -p src/report && cat > src/report/export.ts <<'EOF'
import { mkdir, rename, writeFile, rm } from "node:fs/promises";
import { join } from "node:path";

export interface ExportableRun {
  review: unknown;
  plan?: unknown;
  replays?: unknown[];
  gate?: unknown[];
}

async function writeAtomic(path: string, body: string): Promise<void> {
  const tmp = `${path}.${process.pid}.${crypto.randomUUID()}.tmp`;
  try {
    await writeFile(tmp, body);
    await rename(tmp, path);
  } catch (err) {
    await rm(tmp, { force: true });
    throw err;
  }
}

export async function exportRun(run: ExportableRun, outDir: string): Promise<string[]> {
  await mkdir(outDir, { recursive: true });
  const generatedAt = new Date().toISOString();
  const files: [string, unknown][] = [["review.json", run.review]];
  if (run.plan !== undefined) files.push(["plan.json", run.plan]);
  if (run.replays !== undefined) files.push(["replays.json", run.replays]);
  if (run.gate !== undefined) files.push(["gate.json", run.gate]);

  const paths: string[] = [];
  for (const [name, data] of files) {
    const path = join(outDir, name);
    await writeAtomic(path, JSON.stringify({ schemaVersion: 1, generatedAt, data }, null, 2) + "\n");
    paths.push(path);
  }
  return paths.sort();
}
EOF
cat > tests/report-export.test.ts <<'EOF'
import { test, expect } from "bun:test";
import { mkdtempSync, readFileSync, readdirSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { exportRun } from "../src/report/export";

const tmp = () => mkdtempSync(join(tmpdir(), "export-"));
const read = (p: string) => JSON.parse(readFileSync(p, "utf8"));

test("writes only review.json when optional parts are absent", async () => {
  const dir = tmp();
  const paths = await exportRun({ review: { a: 1 } }, join(dir, "nested"));
  expect(paths).toEqual([join(dir, "nested", "review.json")]);
  const f = read(paths[0]!);
  expect(f.schemaVersion).toBe(1);
  expect(f.data).toEqual({ a: 1 });
  expect(typeof f.generatedAt).toBe("string");
});

test("writes all files, sorted, no temp files left", async () => {
  const dir = tmp();
  const paths = await exportRun({ review: 1, plan: 2, replays: [3], gate: [4] }, dir);
  expect(paths.map((p) => p.slice(dir.length + 1))).toEqual(["gate.json", "plan.json", "replays.json", "review.json"]);
  expect(readdirSync(dir).sort()).toEqual(["gate.json", "plan.json", "replays.json", "review.json"]);
});

test("re-export overwrites; only generatedAt differs", async () => {
  const dir = tmp();
  const run = { review: { x: [1, 2] }, gate: [] };
  const [gate] = await exportRun(run, dir).then((p) => p.filter((x) => x.endsWith("gate.json")));
  const a = read(gate!);
  await new Promise((r) => setTimeout(r, 5));
  await exportRun(run, dir);
  const b = read(gate!);
  expect(b.generatedAt).not.toBe(a.generatedAt);
  expect({ ...b, generatedAt: 0 }).toEqual({ ...a, generatedAt: 0 });
  expect(b.data).toEqual([]);
});
EOF
bun test tests/report-export.test.ts 2>&1 | tail -8; bun run typecheck 2>&1 | tail -5; bun test 2>&1 | tail -5

